import React, { useState } from "react";
import "./CreateGroupPage.css"; // Include your styles
import Navbar from "../components/navbar"; // Your Navbar component
import Footer from "../components/footer"; // Your Footer component
import AdminSidebar from "../components/AdminSideBar";
import "./SubmitProposal.css";

function CreateGroupPage() {
  const [groupName, setGroupName] = useState(""); // Group name
  const [projectName, setProjectName] = useState(""); // Project name
  const [members, setMembers] = useState([]); // List of members
  const [memberName, setMemberName] = useState(""); // Temporary member name input
  const [allGroups, setAllGroups] = useState([]); // List of all created groups

  // Handle form submission to create a group
  const handleGroupCreation = (e) => {
    e.preventDefault();
    if (groupName.trim() && projectName.trim() && members.length > 0) {
      const newGroup = {
        groupName,
        projectName,
        members,
      };

      setAllGroups([...allGroups, newGroup]);

      // Reset inputs after group creation
      setGroupName("");
      setProjectName("");
      setMembers([]);
    } else {
      alert("Please fill in all fields and add members to the group.");
    }
  };

  // Handle adding a member to the group
  const handleAddMember = (e) => {
    e.preventDefault();
    if (memberName.trim()) {
      if (members.length < 4) {
        setMembers([...members, memberName]);
        setMemberName(""); // Clear the member name input
      } else {
        alert("You can add up to 4 members per group.");
      }
    } else {
      alert("Please enter a member's name.");
    }
  };

  return (
    <div className="proposal-container">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="create-group-section">
          <div className="form-container">
            <h2>Create a New Group</h2>
            <form onSubmit={handleGroupCreation}>
              <div className="input-group">
                <label htmlFor="group-name">Group Name</label>
                <input
                  type="text"
                  id="group-name"
                  value={groupName}
                  onChange={(e) => setGroupName(e.target.value)}
                  placeholder="Enter group name"
                  required
                />
              </div>

              <div className="input-group">
                <label htmlFor="project-name">Project Name</label>
                <input
                  type="text"
                  id="project-name"
                  value={projectName}
                  onChange={(e) => setProjectName(e.target.value)}
                  placeholder="Enter project name"
                  required
                />
              </div>

              <div className="input-group">
                <label htmlFor="member-name">Add Member</label>
                <input
                  type="text"
                  id="member-name"
                  value={memberName}
                  onChange={(e) => setMemberName(e.target.value)}
                  placeholder="Enter member name"
                />
                <button type="button" onClick={handleAddMember}>
                  Add Member
                </button>
              </div>

              {members.length > 0 && (
                <div className="members-list">
                  <h3>Members:</h3>
                  <ul>
                    {members.map((member, index) => (
                      <li key={index}>{member}</li> // Removed the "Remove" button
                    ))}
                  </ul>
                </div>
              )}

              <button type="submit" className="submit-button">Create Group</button>
            </form>
          </div>

          <div className="groups-list">
            <h3>All Groups</h3>
            {allGroups.length > 0 ? (
              <table>
                <thead>
                  <tr>
                    <th>Group Name</th>
                    <th>Project Name</th>
                    <th>Members</th>
                  </tr>
                </thead>
                <tbody>
                  {allGroups.map((group, index) => (
                    <tr key={index}>
                      <td>{group.groupName}</td>
                      <td>{group.projectName}</td>
                      <td>
                        <ul>
                          {group.members.map((member, memberIndex) => (
                            <li key={memberIndex}>{member}</li>
                          ))}
                        </ul>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            ) : (
              <p>No groups have been created yet.</p>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default CreateGroupPage;
